import { useAuth } from "../hooks/useAuth";
import { Link } from "react-router-dom";

export default function Profil() {
  const { utilisateur } = useAuth();

  if (!utilisateur) {
    return (
      <div style={styles.container}>
        <p style={styles.notConnected}>
          Vous n'êtes pas connecté.
        </p>
        <Link to="/connexion" style={styles.loginLink}>
          Se connecter
        </Link>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        
        {/* Avatar */}
        <div style={styles.avatar}>
          {utilisateur.nom?.charAt(0).toUpperCase()}
        </div>

        <h2 style={styles.title}>Mon Profil</h2>

        {/* Infos */}
        <div style={styles.infoBox}>
          <p><strong>Nom :</strong> {utilisateur.nom}</p>
          <p><strong>Email :</strong> {utilisateur.email}</p>
        </div>

        {/* Actions */}
        <div style={styles.actions}>
          <Link to="/mes-commandes">
            <button style={styles.primaryBtn}>
              Mes commandes
            </button>
          </Link>

          <Link to="/catalogue">
            <button style={styles.secondaryBtn}>
              Continuer mes achats
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "80vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "#f5f6fa",
    padding: "20px",
  },

  card: {
    width: "100%",
    maxWidth: "420px",
    background: "white",
    borderRadius: "16px",
    padding: "30px",
    boxShadow: "0 8px 25px rgba(0,0,0,0.08)",
    textAlign: "center",
  },

  avatar: {
    width: "80px",
    height: "80px",
    borderRadius: "50%",
    background: "#3B5BDB",
    color: "white",
    fontSize: "32px",
    fontWeight: "bold",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    margin: "0 auto 20px",
  },

  title: {
    marginBottom: "20px",
    color: "#333",
  },

  infoBox: {
    background: "#f1f3f5",
    padding: "15px",
    borderRadius: "10px",
    textAlign: "left",
    marginBottom: "25px",
    lineHeight: "1.8",
  },

  actions: {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  },

  primaryBtn: {
    width: "100%",
    background: "#3B5BDB",
    color: "white",
    border: "none",
    padding: "12px",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold",
  },

  secondaryBtn: {
    width: "100%",
    background: "transparent",
    border: "2px solid #3B5BDB",
    color: "#3B5BDB",
    padding: "12px",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold",
  },

  container: {
    textAlign: "center",
    padding: "60px",
  },

  notConnected: {
    marginBottom: "10px",
    fontSize: "18px",
  },

  loginLink: {
    color: "#3B5BDB",
    fontWeight: "bold",
    textDecoration: "none",
  },
};
